def add_relative_noise(x_true, eps, rng):
    """Relative (multiplicative) noise, as in the DINN generator notebooks.

    ``repo/Experiments/noise/covid_noise_0.01.ipynb`` builds the 1 % data as

        S_noise = (1 + noise * randn(1, len(t))[0]) * sidr_data[1]      (and
        likewise for I, D, R)  -- i.e.  x~_c(t_i) = (1 + eps * xi_i) x_c(t_i)

    with independent xi per compartment and sample.  This is *not* the additive
    max-scaled recipe of paper section 5.1 / R7; it is kept here only as a
    sensitivity branch.
    """
    x_true = np.asarray(x_true, dtype=float)
    if eps == 0.0:
        return x_true.copy()
    return x_true * (1.0 + eps * rng.standard_normal(x_true.shape))


